import csv


def count_lines_containing(path, keyword, exclude=None):
    with open(path, encoding="utf-8") as f:
        reader = csv.DictReader(f)
        count = 0
        for row in reader:
            title = row["title"].lower()
            if keyword.lower() not in title:
                continue
            if exclude and exclude.lower() in title:
                continue
            count += 1
    return count
